#include "eapol_wire.h"
static int apart(const void*a,unsigned n,const void*b,unsigned m){return a&&b&&(uintptr_t)a<=UINTPTR_MAX-n&&(uintptr_t)b<=UINTPTR_MAX-m&&((uintptr_t)a+n<=(uintptr_t)b||(uintptr_t)b+m<=(uintptr_t)a);}
unsigned qsg_eapol_frame(const StaJoin*s,uint64_t epoch,const uint8_t*p,unsigned n,uint16_t seq,uint8_t*out,unsigned cap){if(!s||!p||!out||s->epoch!=epoch||!epoch||s->quarantined||!s->associated||!s->mapped||s->pending||s->ptk||s->gtk||s->core_completed||seq>4095||n<99||n>1700||cap<32+n||!apart(out,32+n,s,sizeof(*s))||!apart(out,32+n,p,n)||p[0]<1||p[0]>3||p[1]!=3||(((unsigned)p[2]<<8)|p[3])!=n-4)return 0;uint8_t h[32]={8,1};for(unsigned j=0;j<6;j++){h[4+j]=s->peer[j];h[10+j]=s->own_mac[j];h[16+j]=s->peer[j];}h[22]=(uint8_t)(seq<<4);h[23]=(uint8_t)(seq>>4);h[24]=0xaa;h[25]=0xaa;h[26]=3;h[30]=0x88;h[31]=0x8e;for(unsigned j=0;j<32;j++)out[j]=h[j];for(unsigned j=0;j<n;j++)out[32+j]=p[j];return 32+n;}
